export interface OrderLine {
  slug: string
  name: string
  qty: number
}

/** An order as the API returns it. Amounts use the server format, e.g. `19.99 USD`. */
export interface Order {
  id: string
  lines: OrderLine[]
  subtotal: string
  discount: string
  total: string
}

import type { CartLine } from '#shared/types/cart'
import type { Order, OrderLine } from '#shared/types/order'
import { randomUUID } from 'node:crypto'
import { findProduct } from '#server/utils/db'
import { computeQuote } from '#server/utils/quote'

/** Orders live in server memory only, so they are lost on restart. */
const orders = new Map<string, Order>()

export class UnknownProductError extends Error {}

/**
 * Stores an order priced by the same quote logic as `/api/cart/quote`.
 * Throws `UnknownProductError` when a line refers to a product that does not exist.
 */
export function placeOrder(lines: CartLine[], code?: string): Order {
  if (!lines.length)
    throw new UnknownProductError('The order has no lines')
  const orderLines: OrderLine[] = lines.map((line) => {
    const product = findProduct(line.slug)
    if (!product)
      throw new UnknownProductError(`Unknown product: ${line.slug}`)
    return { slug: line.slug, name: product.name, qty: line.qty }
  })
  const order: Order = {
    id: randomUUID(),
    lines: orderLines,
    ...computeQuote(lines, code),
  }
  orders.set(order.id, order)
  return order
}

export function getOrder(id: string): Order | undefined {
  return orders.get(id)
}

import type { CartLine } from '#shared/types/cart'
import { createError, defineEventHandler, readBody } from 'h3'
import { placeOrder, UnknownProductError } from '#server/utils/orders'

export default defineEventHandler(async (event) => {
  const body = await readBody<{ lines?: CartLine[], code?: string }>(event)
  try {
    const order = placeOrder(body?.lines ?? [], body?.code)
    return { id: order.id, subtotal: order.subtotal, discount: order.discount, total: order.total }
  }
  catch (error) {
    if (error instanceof UnknownProductError)
      throw createError({ statusCode: 400, statusMessage: error.message })
    throw error
  }
})

import { createError, defineEventHandler, getRouterParam } from 'h3'
import { getOrder } from '#server/utils/orders'

export default defineEventHandler((event) => {
  const order = getOrder(getRouterParam(event, 'id') ?? '')
  if (!order)
    throw createError({ statusCode: 404, statusMessage: 'Order not found' })
  return order
})
